-- public.folk_row(p_world uuid, p_uid uuid, p_near boolean)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.folk_row(p_world uuid, p_uid uuid, p_near boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select jsonb_build_object(
    'uid', p_uid,
    'name', folk_name(p_world, p_uid),
    'online', afoot(p_world, p_uid))
    || case when p_near and afoot(p_world, p_uid)
            then coalesce((select jsonb_build_object('x', floor(p.x)::int, 'y', floor(p.y)::int)
                           from player p where p.world_id = p_world and p.uid = p_uid), '{}'::jsonb)
            else '{}'::jsonb end
$function$
